/** SKU 档案记录 */
export interface SkuRecord {
  id: string; // crypto.randomUUID()
  name: string;
  createdAt: number;
}

/** 特征库条目：一条特征向量隶属一个 SKU；向量由插件返回，已做 L2 归一化 */
export interface VectorEntry {
  skuId: string;
  vector: number[];
}

/** SKU 级命中结果：score 为该 SKU 全部向量中的最高余弦相似度 */
export interface MatchResult {
  skuId: string;
  score: number;
}

/** 原生插件一次特征提取的结果 */
export interface ExtractResult {
  vector: number[]; // L2 归一化后的特征向量
  elapsedMs: number; // 原生侧计时：解码 + 预处理 + 推理
  backend: 'gpu' | 'cpu'; // 实际使用的推理后端（GPU 不可用时插件自动回退 CPU）
}

/** 模型加载信息 */
export interface ModelInfo {
  backend: 'gpu' | 'cpu';
  inputSize: number; // 模型输入边长（正方形），如 224
  vectorDim: number; // 输出向量维度，如 1280
}

// ---------- matcher.ts 语义（纯函数，禁止依赖 Capacitor / DOM / localforage） ----------

/** 余弦相似度。维度不等抛 Error；任一零向量返回 0；值域 [-1, 1] */
export type CosineSimilarity = (a: number[], b: number[]) => number;

/**
 * SKU 级 Top-N：
 * - 按 SKU 聚合，score 取该 SKU 全部向量与 query 的最高余弦相似度；
 * - 结果按 score 降序，至多 n 条；同分按 skuId 字典序稳定排序；
 * - entries 为空或 n <= 0 时返回 []。
 */
export type TopNBySku = (query: number[], entries: VectorEntry[], n: number) => MatchResult[];

// ---------- vectorStore.ts 语义 ----------

/** 可注入的 KV 后端（默认实现用 localforage；测试用内存实现） */
export interface KeyValueBackend {
  get(key: string): Promise<string | null>;
  set(key: string, value: string): Promise<void>;
  remove(key: string): Promise<void>;
  keys(): Promise<string[]>;
}

export interface VectorStore {
  listSkus(): Promise<SkuRecord[]>;
  createSku(name: string): Promise<SkuRecord>;
  /** 为既有 SKU 追加特征向量；skuId 不存在抛 Error */
  addVectors(skuId: string, vectors: number[][]): Promise<void>;
  /** 全量取出（SKU 档案 + 向量条目），供比对使用 */
  getEntries(): Promise<VectorEntry[]>;
  /** 删除 SKU 及其全部向量 */
  deleteSku(skuId: string): Promise<void>;
  /**
   * BenchView 千级扩展性用：追加 skuCount 个名为 MOCK-<i> 的 SKU，
   * 每个 vectorsPerSku 条 dim 维的 L2 归一化随机向量；不清除已有数据。
   */
  fillRandom(skuCount: number, vectorsPerSku: number, dim: number): Promise<void>;
  clearAll(): Promise<void>;
}

export type VectorStoreFactory = (backend?: KeyValueBackend) => VectorStore;

// ---------- 原生插件契约（extractor.ts 经 registerPlugin 直连，无插件侧 web 包） ----------

export const FEATURE_EXTRACTOR_PLUGIN_NAME = 'FeatureExtractor';

export interface FeatureExtractorPlugin {
  /** 加载 assets/model.tflite；GPU 委托失败自动回退 CPU 并在返回值中标注 */
  loadModel(): Promise<ModelInfo>;
  /** imageBase64：不含 data: 前缀的纯 base64；返回 L2 归一化向量 */
  extract(options: { imageBase64: string }): Promise<ExtractResult>;
}
