```ts
const exportNotice = ref('');

async function exportJson(): Promise<void> {
  if (!summary.value) return;
  exportNotice.value = '';
  const payload = {...};
  const json = JSON.stringify(payload, null, 2);
  // 真机 WebView 未注册 DownloadListener，Blob 下载会静默失效 → 原生端直接走剪贴板
  const isNative = Boolean((window as any).Capacitor?.isNativePlatform?.());
  if (!isNative) {
    try {
      const blob = new Blob([json], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      const stamp = new Date().toISOString().replace(/[:.]/g, '-');
      anchor.href = url;
      anchor.download = `bench-${stamp}.json`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      URL.revokeObjectURL(url);
      exportNotice.value = '已导出 JSON 文件。';
      return;
    } catch {
      // 落入剪贴板降级
    }
  }
  await navigator.clipboard.writeText(json);
  exportNotice.value = '已复制 JSON 到剪贴板（真机 WebView 不支持文件下载）。';
}
```

Use `import { Capacitor } from '@capacitor/core'` instead of window hack — cleaner. Capacitor.isNativePlatform() exists in @capacitor/core v7.

